def copy_image_to_media(apps, schema_editor):
    Post = apps.get_model('apps', 'Post')
    PostMedia = apps.get_model('apps', 'PostMedia')
    PostMedia.objects.bulk_create([
        PostMedia(post=post, file=post.image.name, media_type='image', order=0)
        for post in Post.objects.exclude(image='')
    ])


def copy_media_to_image(apps, schema_editor):
    Post = apps.get_model('apps', 'Post')
    for post in Post.objects.prefetch_related('media'):
        first = post.media.order_by('order').first()
        if first:
            post.image = first.file.name
            post.save(update_fields=['image'])


